"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[9632],{1431(t,e,r){r.r(e),r.d(e,{assets:()=>c,contentTitle:()=>l,default:()=>u,frontMatter:()=>p,metadata:()=>a,toc:()=>d});const a=JSON.parse('{"id":"part3-agent-protocols/index","title":"Part III \u2014 Agent Protocols & Integration","description":"How modern AI applications connect to tools, data, and other agents. Chapters 1\u20134 are the MCP track: from first principles, through discovery + remote + auth, into a concrete enterprise pattern, and finally the protoc...","source":"@site/docs/part3-agent-protocols/index.mdx","sourceDirName":"part3-agent-protocols","slug":"/part3-agent-protocols/overview","permalink":"/tutorials/part3-agent-protocols/overview","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"frontMatter":{"title":"Part III \u2014 Agent Protocols & Integration","slug":"/part3-agent-protocols/overview","description":"How modern AI applications connect to tools, data, and other agents. Chapters 1\u20134 are the MCP track: from first principles, through discovery + remote + auth, into a concrete enterprise pattern, and finally the protoc...","sidebar_label":"Part overview","pagination_label":"Part overview","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"16. GitHub governance and CI","permalink":"/tutorials/part2-backend-platform-security/14-github-governance"},"next":{"title":"1. MCP fundamentals","permalink":"/tutorials/part3-agent-protocols/01-mcp-fundamentals"}}');var o=r(4848),n=r(8453),i=r(8172);const s=JSON.parse('{"sourcePath":"part3-agent-protocols/index.html","route":"/part3-agent-protocols/overview","kind":"part","partId":"part3","partLabel":"Part III - Agent Protocols & Integration","accent":"violet","heading":"Part III \u2014 Agent Protocols & Integration","title":"Part III \u2014 Agent Protocols & Integration","description":"How modern AI applications connect to tools, data, and other agents. Chapters 1\u20134 are the MCP track: from first principles, through discovery + remote + auth, into a concrete enterprise pattern, and finally the protoc...","readingMinutes":1,"bodyClass":"","normalizeMath":false,"toc":[{"id":"chapters-in-order","label":"Chapters in order"}],"html":"<p>How modern AI applications connect to tools, data, and other agents.\\nChapters 1\u20134 are the <strong>MCP track</strong>: from first principles, through\\ndiscovery + remote + auth, into a concrete enterprise pattern, and finally\\nthe protocol\'s 2025-to-2026 evolution. Chapter 5 covers stable\\n<strong>A2A 1.0</strong> for multi-agent collaboration. Chapter 6 is a\\nself-contained JavaScript/TypeScript\\nprimer used by Chapter 7\'s LangChain \u2192 LangGraph \u2192 Flowise journey.</p>\\n\\n<div class=\\"tr-tip\\">\\n  <strong>Prerequisites</strong>\\n  Comfortable with Python and HTTP basics. Part II Chapters 1\u20133 (FastAPI &amp;\\n  Uvicorn, HTTP methods, request mapping) are recommended before the MCP\\n  track. The auth deep\u2011dive (Part II Ch. 7\u201311) makes Chapters 2 and 4\\n  easier to follow.\\n</div>\\n\\n<div class=\\"tr-update\\">\\n  <strong>What changed after the first MCP examples</strong>\\n  The 2025 protocol family introduced Streamable HTTP, protected-resource\\n  authorization, elicitation, structured tool output, and resource links.\\n  The <code>2026-07-28</code> core then removed protocol sessions and the\\n  mandatory initialize handshake, added <code>server/discover</code>, moved\\n  tasks to an extension, and made continuation input explicit. Chapter 4\\n  teaches this evolution without mixing the wire formats.\\n</div>\\n\\n<div class=\\"tr-note\\">\\n  <strong>MCP reading path</strong>\\n  Chapter 1 is the beginner local example. Chapter 2 is the primary MCP\\n  technical chapter: components, discovery, remote servers, auth, token\\n  acquisition, validation, and best practices. Chapter 3 applies the same\\n  concepts to an enterprise FastAPI-to-Salesforce pattern. Chapter 4 is not a\\n  replacement for the earlier chapters; it preserves the 2025 foundation and\\n  then maps it to the current stateless protocol.\\n</div>\\n\\n<h2 id=\\"chapters-in-order\\">Chapters in order</h2>\\n<ol>\\n  <li><a href=\\"/tutorials/part3-agent-protocols/01-mcp-fundamentals\\">MCP fundamentals \u2014 tools, resources, prompts (DB example)</a></li>\\n  <li><a href=\\"/tutorials/part3-agent-protocols/02-mcp-discovery-remote-auth\\">MCP discovery, remote servers, authentication</a></li>\\n  <li><a href=\\"/tutorials/part3-agent-protocols/03-mcp-enterprise-pattern\\">MCP enterprise pattern (FastAPI host \u2192 MCP \u2192 Salesforce)</a></li>\\n  <li><a href=\\"/tutorials/part3-agent-protocols/04-mcp-2025-update\\">MCP protocol evolution \u2014 2025 foundations to the 2026 stateless core</a></li>\\n  <li><a href=\\"/tutorials/part3-agent-protocols/05-a2a-protocol\\">A2A 1.0 \u2014 discovery, delegation, and task lifecycle</a></li>\\n  <li><a href=\\"/tutorials/part3-agent-protocols/06-javascript-typescript-primer\\">JavaScript &amp; TypeScript primer</a></li>\\n  <li><a href=\\"/tutorials/part3-agent-protocols/07-langchain-langgraph-flowise\\">LangChain \u2192 LangGraph \u2192 Flowise</a></li>\\n</ol>"}'),p={title:"Part III \u2014 Agent Protocols & Integration",slug:"/part3-agent-protocols/overview",description:"How modern AI applications connect to tools, data, and other agents. Chapters 1\u20134 are the MCP track: from first principles, through discovery + remote + auth, into a concrete enterprise pattern, and finally the protoc...",sidebar_label:"Part overview",pagination_label:"Part overview",hide_title:!0,hide_table_of_contents:!0},l=void 0,c={},d=[];function h(t){return(0,o.jsx)(i.A,{content:s})}function u(t={}){const{wrapper:e}={...(0,n.R)(),...t.components};return e?(0,o.jsx)(e,{...t,children:(0,o.jsx)(h,{...t})}):h()}}}]);